class Solution:
    def isReflected(self, points: List[List[int]]) -> bool:
        n = len(points)
        pts = [tuple(p) for p in points]
        axes = set()
        for i in range(n):
            for j in range(i, n):
                if pts[i][1] == pts[j][1]:
                    axes.add((pts[i][0] + pts[j][0]) / 2)
        for c in axes:
            ok = True
            for x, y in pts:
                if (2 * c - x, y) not in set(pts):
                    ok = False
                    break
            if ok:
                return True
        return False

