class Solution {
public:
    bool isReflected(vector<vector<int>>& points) {
        int n = points.size();
        set<pair<long long,long long>> s;
        for (auto& p : points) s.insert({p[0], p[1]});
        vector<pair<long long,long long>> v(s.begin(), s.end());
        int m = v.size();
        for (int i = 0; i < m; i++) {
            for (int j = i; j < m; j++) {
                if (v[i].second != v[j].second) continue;
                double c = (v[i].first + v[j].first) / 2.0;
                bool ok = true;
                for (auto& p : v) {
                    if (!s.count({(long long)llround(2*c - p.first), p.second})) { ok = false; break; }
                }
                if (ok) return true;
            }
        }
        return m == 1;
    }
};

