class Solution {
    public boolean isReflected(int[][] points) {
        int n = points.length;
        Set<Long> set = new HashSet<>();
        List<long[]> v = new ArrayList<>();
        for (int[] p : points) {
            long key = ((long)p[0] << 32) | (p[1] & 0xffffffffL);
            if (set.add(key)) v.add(new long[]{p[0], p[1]});
        }
        int m = v.size();
        for (int i = 0; i < m; i++) {
            for (int j = i; j < m; j++) {
                if (v.get(i)[1] != v.get(j)[1]) continue;
                double c = (v.get(i)[0] + v.get(j)[0]) / 2.0;
                boolean ok = true;
                for (long[] p : v) {
                    long mx = Math.round(2 * c - p[0]);
                    if (!set.contains((mx << 32) | (p[1] & 0xffffffffL))) { ok = false; break; }
                }
                if (ok) return true;
            }
        }
        return m == 1;
    }
}

