var isReflected = function(points) {
    const key = (x, y) => x + ',' + y;
    const set = new Set(points.map(p => key(p[0], p[1])));
    const uniq = [...set].map(s => s.split(',').map(Number));
    const m = uniq.length;
    for (let i = 0; i < m; i++) {
        for (let j = i; j < m; j++) {
            if (uniq[i][1] !== uniq[j][1]) continue;
            const c = (uniq[i][0] + uniq[j][0]) / 2;
            let ok = true;
            for (const [x, y] of uniq) {
                if (!set.has(key(2 * c - x, y))) { ok = false; break; }
            }
            if (ok) return true;
        }
    }
    return m === 1;
};

