class Solution:
    def isReflected(self, points: List[List[int]]) -> bool:
        pts = {(x, y) for x, y in points}
        minX = min(x for x, _ in pts)
        maxX = max(x for x, _ in pts)
        s = minX + maxX
        return all((s - x, y) in pts for x, y in pts)

